use std::fmt;
use std::str::FromStr;

#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
enum Level {
    Debug,
    Info,
    Warn,
    Error,
}

impl FromStr for Level {
    type Err = ();
    fn from_str(s: &str) -> Result<Level, ()> {
        match s.to_ascii_lowercase().as_str() {
            "debug" => Ok(Level::Debug),
            "info" => Ok(Level::Info),
            "warn" => Ok(Level::Warn),
            "error" => Ok(Level::Error),
            _ => Err(()),
        }
    }
}

#[derive(Debug, PartialEq)]
struct Options {
    level: Level,
    top: usize,
    sources: Vec<String>,
    help: bool,
}

#[derive(Debug, PartialEq)]
enum ArgError {
    Unknown(String),
    MissingValue(String),
    BadValue { option: String, value: String },
}

impl fmt::Display for ArgError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            ArgError::Unknown(a) => write!(f, "unknown argument '{a}'"),
            ArgError::MissingValue(o) => write!(f, "{o} needs a value"),
            ArgError::BadValue { option, value } => write!(f, "invalid value '{value}' for {option}"),
        }
    }
}

fn parse_args(args: &[&str]) -> Result<Options, ArgError> {
    let mut opts = Options { level: Level::Debug, top: 5, sources: Vec::new(), help: false };
    let mut i = 0;
    while i < args.len() {
        let arg = args[i];
        let (name, inline) = match arg.split_once('=') {
            Some((n, v)) if n.starts_with("--") => (n, Some(v.to_string())),
            _ => (arg, None),
        };
        let mut value = |i: &mut usize| -> Result<String, ArgError> {
            if let Some(v) = inline.clone() {
                return Ok(v);
            }
            *i += 1;
            args.get(*i).map(|v| v.to_string()).ok_or_else(|| ArgError::MissingValue(name.to_string()))
        };
        let bad = |v: &str| ArgError::BadValue { option: name.to_string(), value: v.to_string() };
        match name {
            "-h" | "--help" => opts.help = true,
            "--level" => {
                let v = value(&mut i)?;
                opts.level = v.parse().map_err(|_| bad(&v))?;
            }
            "--top" => {
                let v = value(&mut i)?;
                opts.top = match v.parse::<usize>() {
                    Ok(n) if n >= 1 => n,
                    _ => return Err(bad(&v)),
                };
            }
            "--source" => {
                let v = value(&mut i)?;
                opts.sources.push(v);
            }
            _ => return Err(ArgError::Unknown(arg.to_string())),
        }
        i += 1;
    }
    Ok(opts)
}

unitTests:
let defaults = Options { level: Level::Debug, top: 5, sources: vec![], help: false };

test("levels parse and order", || {
    check_eq("WARN".parse::<Level>(), Ok(Level::Warn));
    check_eq("info".parse::<Level>(), Ok(Level::Info));
    check_eq("loud".parse::<Level>(), Err(()));
    check(Level::Error > Level::Warn && Level::Debug < Level::Info);
});

test("options", || {
    check_eq(parse_args(&[]), Ok(Options { ..defaults }));
    check_eq(parse_args(&["--level", "error", "--top", "3", "--source", "auth", "--source=db"]),
             Ok(Options { level: Level::Error, top: 3, sources: vec!["auth".into(), "db".into()], help: false }));
    check_eq(parse_args(&["--top=10", "-h"]).map(|o| (o.top, o.help)), Ok((10, true)));
});

test("errors", || {
    check_eq(parse_args(&["--verbose"]), Err(ArgError::Unknown("--verbose".into())));
    check_eq(parse_args(&["--level"]), Err(ArgError::MissingValue("--level".into())));
    check_eq(parse_args(&["--top", "0"]), Err(ArgError::BadValue { option: "--top".into(), value: "0".into() }));
    check_eq(parse_args(&["--level=loud"]), Err(ArgError::BadValue { option: "--level".into(), value: "loud".into() }));
    check_eq(parse_args(&["file.log"]), Err(ArgError::Unknown("file.log".into())));
});

test("messages", || {
    check_eq(ArgError::Unknown("-x".into()).to_string(), "unknown argument '-x'");
    check_eq(ArgError::MissingValue("--top".into()).to_string(), "--top needs a value");
    check_eq(ArgError::BadValue { option: "--top".into(), value: "lots".into() }.to_string(), "invalid value 'lots' for --top");
});

